valid.text:
switch(foo) { case 0: a();
/* This falls through intentionally */
case 1: b(); }

invalid.text:
switch(foo) { case 0: a();
/* intentional */
case 1: b(); }

switch(foo) { case 0: a();
case 1: b();
case 2: c(); break; }

excluded.text:
switch(foo) { case 0: a();
/* break omitted */
case 1: b(); }

switch(foo) { case 0: a();
/* skip fallthrough */
case 1: b(); }

switch(foo) { case 0: a();
/* break omitted */
case 1: b(); }
